<script setup lang="ts">
import{reactive,ref,onMounted}from'vue';import{api,idemKey}from'../api';import{useAuthStore}from'../stores/auth';import{ElMessage}from'element-plus';const auth=useAuthStore(),wallet=ref<any>({}),rows=ref<any[]>([]),dialog=ref(false),tenantId=ref(2),form=reactive({amountCent:100000,remark:'Demo 账户充值'});const params=()=>auth.isAdmin?{tenantId:tenantId.value}:{};const load=async()=>{wallet.value=await api.get('/wallet',{params:params()});const data:any=await api.get('/billing/ledgers',{params:params()});rows.value=data.items};const recharge=async()=>{await api.post('/wallet/recharges',{...form,tenantId:auth.isAdmin?tenantId.value:null},{headers:{'Idempotency-Key':idemKey()}});dialog.value=false;ElMessage.success('充值成功');load()};const money=(v:number)=>`¥${((v||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;onMounted(load)
</script>
<template><div class="toolbar" v-if="auth.isAdmin"><div><span class="muted">当前查看租户 ID：</span><el-input-number v-model="tenantId" :min="1" @change="load"/></div></div><div class="grid stats" style="grid-template-columns:repeat(3,1fr)"><div class="panel stat"><div class="label">可用余额</div><div class="value success">{{money(wallet.availableCent)}}</div><div class="hint">可用于新订单冻结</div></div><div class="panel stat"><div class="label">冻结金额</div><div class="value">{{money(wallet.frozenCent)}}</div><div class="hint">等待引擎最终回调</div></div><div class="panel stat"><div class="label">账户总额</div><div class="value">{{money((wallet.availableCent||0)+(wallet.frozenCent||0))}}</div><el-button v-if="auth.can('billing:recharge')" type="primary" link @click="dialog=true">模拟充值 →</el-button></div></div><div class="panel"><div class="panel-title"><h3>不可变账务流水</h3><span class="muted">相同业务号 + 流水类型仅允许一次</span></div><el-table :data="rows"><el-table-column prop="ledgerNo" label="流水号"/><el-table-column prop="bizNo" label="业务号"/><el-table-column prop="type" label="类型"><template #default="s"><el-tag :type="s.row.type==='DEDUCT'?'danger':s.row.type==='FREEZE'?'warning':'success'">{{s.row.type}}</el-tag></template></el-table-column><el-table-column label="可用变动"><template #default="s"><span :class="s.row.deltaAvailableCent<0?'danger':'success'">{{money(s.row.deltaAvailableCent)}}</span></template></el-table-column><el-table-column label="冻结变动"><template #default="s">{{money(s.row.deltaFrozenCent)}}</template></el-table-column><el-table-column label="余额快照"><template #default="s">{{money(s.row.availableAfterCent)}} / {{money(s.row.frozenAfterCent)}}</template></el-table-column><el-table-column prop="remark" label="说明"/></el-table></div><el-dialog v-model="dialog" title="模拟钱包充值" width="430"><el-form label-width="90"><el-form-item label="金额（分）"><el-input-number v-model="form.amountCent" :min="1" :max="100000000"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="recharge">确认充值</el-button></template></el-dialog></template>
